import { BeforeConnectInterceptor, BeforeStartConnectInterceptor, ObjectFactory, BeforeMoveConnectionInterceptor, BeforeDetachInterceptor, BeforeStartDetachInterceptor, VertexUpdatedReason } from "./toolkit";
import { Vertex, Port, Node, Group, Edge, ObjectData, Graph, Base } from "./model/graph";
import { FilterableDataset } from "./filterable-dataset";
import { DataModel } from "./datamodel/data-model";
import { VisuallyJsRenderer } from './renderer';
import { TransactionCleanupAction } from "./undo-redo/undo-redo";
import { PointXY } from "./util";
/**
 * Return value from getObjectInfo - an object, its type, and id. Or null.
 * @group Model
 */
export interface ObjectInfo<T> {
    type?: string;
    obj?: T;
    id?: string;
}
/**
 * Data source for a renderer.
 * @group Model
 */
export interface DataSource extends FilterableDataset {
    bind<T = any>(evt: string, handler: (p: T) => any, insertAtStart?: boolean): void;
    unbind(evt: string, handler: Function): void;
    fire(evt: string, payload: any, args3?: any): void;
    getType(obj: Base): string;
    getGroups(): Array<Group>;
    getGroup(id: string): Group;
    getGroupType(groupData: ObjectData): string;
    getGroupId(node: ObjectData): string;
    getGroupCount(): number;
    getGroupAt(idx: number): Group;
    getNodes(): Array<Node>;
    getNode(id: string): Node;
    getNodeType(nodeData: ObjectData): string;
    getNodeId(node: ObjectData): string;
    getNodeCount(): number;
    getNodeAt(idx: number): Node;
    getPortType(port: ObjectData): string;
    getPortId(port: ObjectData): string;
    getDescendants(vertex: Group): Array<Node | Group>;
    getAncestors(vertex: Node | Group): Array<Group>;
    isAncestor(focus: Node | Group, possibleAncestor: Group): boolean;
    isDescendantGroup(possibleDescendant: Group, ancestor: Group): boolean;
    getEdgeCount(): number;
    getAllEdges(): Array<Edge>;
    getAllEdgesFor(obj: Vertex, filter?: Function): Array<Edge>;
    getEdge(edgeId: string): Edge;
    edgeFactory: ObjectFactory;
    getEdgeType(edgeData: ObjectData): string;
    getGroup(id: string): Group;
    getGroupCount(): number;
    getGroupAt(idx: number): Group;
    getVertex(id: string): Vertex;
    eachVertex(fn: (idx: number, vertex: Vertex) => void): void;
    resolveFullId(b: Base): string;
    getObjectInfo<T>(obj: any): ObjectInfo<T>;
    beforeConnect: BeforeConnectInterceptor;
    beforeMoveConnection: BeforeMoveConnectionInterceptor;
    beforeStartConnect: BeforeStartConnectInterceptor;
    beforeDetach: BeforeDetachInterceptor;
    beforeStartDetach: BeforeStartDetachInterceptor;
    debugEnabled: boolean;
    getModel(): DataModel;
    getGraph(): Graph;
    reload?(): void;
}
/**
 * Extension of DataSource with methods to write to the model.
 * @group Model
 */
export interface WriteableDatasource extends DataSource {
    $addToGroup(vertex: Node | Group | string, group: Group | string, sourceGroup?: Group, originalPosition?: PointXY, newPosition?: PointXY, source?: VisuallyJsRenderer<any>): boolean;
    $removeFromGroup(node: Node | Group | string, targetGroup?: Group, originalPosition?: PointXY, newPosition?: PointXY, source?: VisuallyJsRenderer<any>): Group;
    updateVertex(vertex: string | Node | Group | Port | ObjectData, updates?: ObjectData, reason?: VertexUpdatedReason | string): void;
    updateVertices(updates: Array<{
        id: string;
        updates?: ObjectData;
    }>, reason?: string, cleanupAction?: TransactionCleanupAction): void;
    openTransaction(cleanupAction?: TransactionCleanupAction): void;
    rollbackTransaction(): void;
    commitTransaction(commitAll?: boolean): void;
    batch(fn: Function): void;
    addEdge(params: any, source?: any): Edge;
    removeEdge(edge: Edge, source?: any): void;
    setEdgeGeometry(edge: Edge, geometry: any, originalGeometry: any, renderer: VisuallyJsRenderer<any>): void;
    addPort(node: string | Node, data: ObjectData): Port;
}
